import numpy as np

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    """Best fit with a bonus for near-perfect fits, weighted by item size."""
    cap = np.max(bins)
    if cap <= 0:
        return np.zeros_like(bins, dtype=float)
    gap = (bins - item) / cap          # normalised leftover space after placing item
    tau = 0.02                          # "near-perfect" threshold
    bonus = 0.5 * (item / cap) * (gap < tau)
    return -gap + bonus

