import numpy as np

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    """Best fit with a bonus for near-perfect fills (leftover below ~1% of capacity)."""
    cap = float(np.max(bins))
    if cap <= 0:
        return np.zeros_like(bins, dtype=float)
    r = (bins - item) / cap
    score = -r + 0.5 * (r < 0.01)
    return score
